<template>
    <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header">
                        <h5 class="modal-title">
                            {{ $t('SharedProductUserList') }}
                        </h5>
                        <button v-on:click="CloseShareUseListPopup($event)" href="javascript:;" class="close"><i
                                class="fa fa-times" aria-hidden="true"></i></button>
                    </div>
                    <div class="modal-body">
                        <div class="listing">
                            <div class="table-responsive tableborder" style="overflow-x:auto;" v-if="!noRecordForTab">
                                <table class="table-sorting table table-bordered" id="table-openactivities-content"
                                    style="width:1500px !important;">
                                    <thead class="thead-bg">
                                        <tr>
                                            <th><span>{{ $t('ProductName') }}</span></th>
                                            <th><span>{{ $t('UniqueName') }} </span></th>
                                            <th><span>{{ $t('IssuedTo') }} </span></th>
                                            <th><span>{{ $t('IssuedBy') }} </span></th>
                                            <th><span>{{ $t('AssignedFrom') }}</span></th>
                                            <th><span>{{ $t('AssignedTill') }} </span></th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        <tr v-for="(item, index) in UserList" :key="index">
                                            <td>{{ item.product_name }}</td>
                                            <td>{{ item.unique_name }}</td>
                                            <td>{{ item.issued_to }}</td>
                                            <td>{{ item.issued_by }}</td>
                                            <td>{{ $options.filters.utcTimezoneToUserTimeZone(item.assigned_from,GetUserInfo.TimeZone) }}</td>
                                            <td>{{ $options.filters.utcTimezoneToUserTimeZone(item.assigned_till,GetUserInfo.TimeZone) }}</td>
                                           
                                        </tr>
                                        <tr v-if="UserList.length == 0" class="text-center text-danger  border no-record">
                                            <td colspan="8" class="text-center text-middle text-danger no-record">
                                             {{ $t('NoRecordfound') }}
                                            </td>
                                          
                                        </tr>
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>
<script>
import DataService from '../../service/DataService';
export default {
    props: {
        aasetcatalogueid: {
            type: Number,
            required: true
        }
    },
    data() {
        return {
            noRecordForTab: false,
            isLoading: false,
            UserList: [],
            
        }
    },
    created: function () {
        this.GetSharedProductUserList();
    },
    methods: {
        
        CloseShareUseListPopup: function () {         
            this.$parent.CloseShareUseListPopup();        
        },
        
        async GetSharedProductUserList() {       
            var url = `id=${this.aasetcatalogueid}`
            await DataService.GetSharedProductUserList(url).then(response => {
                if (response.data != null) {
                    if(response.data.Result.length>0){
                        this.UserList = response.data.Result;
                    }
                    this.noRecordForTab = false;
                } else {
                    this.noRecordForTab = true;
                }
            });
        },
    },

}
</script>